if (TOKENS.tofu && !TOKENS.tofu.img) TOKENS.tofu.img = CARD_ART.m_1;   // les Tofus invoqués (Dofus Vulbis…) ont la tête de la carte Tofu   // les Mini-Gelées invoquées par la Gelée Rouge ont la même tête
