const EXCLUSIVES = { l2: 'eliatrope', mo90: 'koli', fa91: 'koli', ...Object.fromEntries(Array.from({ length: 18 }, (_, i) => ['bc_' + (i + 1), 'bossdrop'])), ...Object.fromEntries(['l5', 'l6', 'l7', 'l8', 'l9', 'l10', 'l15', 'l16', 'l17'].map(id => [id, 'dofus'])) };   // Dofus Émeraude, Dofus Vulbis, Yugo
