// 0.9.9 : les trophées ne sont plus dans les boosters : chacun tombe sur un boss choisi selon son élément (0,3 %)
// 0.9.9 : boucliers et cadrans : plus dans les boosters, ils tombent sur un boss selon leur élément ; rares comme les trophées (boucliers 2 %, cadrans 1 %)
const SHIELD_BOSS = { 'Tofu Royal': 'sh_aerd', 'Gelée Royale': 'sh_akwa', 'Rat Noir': 'sh_terr', 'Meulou': 'sh_feud', 'Dark Vlad': 'sh_air', 'Tengu Givrefoux': 'sh_eau', 'Dragon Cochon': 'sh_feu', 'Minotoror': 'sh_terre' };
const shieldDrop = id => { const c = cardById(id); return !c ? 0 : c.rarity === 'epique' ? 0.01 : 0.02; };   // bouclier niv. 60 : 2 % · cadran niv. 120 : 1 % (un peu sous les panoplies du même boss)
const TROPHY_BOSS = { 'Meulou': 'tr_furi', 'Royalmouth': 'tr_joueur', 'Skeunk': 'tr_acro', 'Tynril': 'tr_savant', 'Chêne Mou': 'tr_vigo',
    'Minotoror': 'tr_furiM', 'Minotot': 'tr_joueurM', 'Crocabulia': 'tr_acroM', 'Torkélonia': 'tr_savantM', 'Tal Kasha': 'tr_vigoM' };
// 0.9.5 : chaque carte de boss a plus d'impact en combat que la meilleure carte épique de même coût (ATK + PV + mots-clés + effets)
const BOSS_BUFFS = [];
(() => {
    const imp = c => n(c.atk) + n(c.pv) + 2.5 * (c.kw || []).length + [...(c.cri || []), ...(c.souffle || []), ...(c.effets || [])].reduce((t, e) => t + 2 + n(e.n) + n(e.atk) + n(e.pv) + 2 * n(e.count), 0);
    const pool = r => BASE_CARDS.filter(c => c.rarity === r && c.type !== 'Sort' && c.type !== 'Boss' && !c.itemId && n(c.atk) + n(c.pv) > 0);
    let ep = pool('epique');
    const best = pa => { const L = ep.filter(c => n(c.pa) <= pa); if (L.length) { const top = Math.max(...L.map(c => n(c.pa))); return Math.max(...L.filter(c => n(c.pa) === top).map(imp)) + Math.max(0, pa - top); }
        const lo = Math.min(...ep.map(c => n(c.pa))); return Math.max(...ep.filter(c => n(c.pa) === lo).map(imp)) * (pa + 3) / (lo + 3); };
    // 0.9.8 : les boss communs (Kardorim, Tournesol Affamé…) se mesurent aux communes, plus aux épiques (ils étaient bien trop forts)
    const epi = ep, com = pool('commun');
    BASE_CARDS.filter(c => c.type === 'Boss').forEach(c => { ep = c.rarity === 'commun' ? com : epi; const t = best(n(c.pa)) + 0.5, a0 = c.atk, p0 = c.pv; let g = 0;
        while (imp(c) < t && g++ < 20) { if (n(c.pv) <= n(c.atk) + 1) c.pv++; else c.atk++; }
        if (c.atk !== a0 || c.pv !== p0) BOSS_BUFFS.push(`${c.nom} ${a0}/${p0} → ${c.atk}/${c.pv}`); });
})();

