        if (i === b.cartes - 1 && b.garanti) { const min = RARITY_ORDER.indexOf(b.garanti), leg = n(b.rates.legendaire), others = RARITY_ORDER.filter((r, x) => x >= min && r !== 'legendaire' && b.rates[r] > 0), sum = others.reduce((t, r) => t + b.rates[r], 0); rates = {}; others.forEach(r => rates[r] = b.rates[r] / sum * (100 - leg)); if (leg) rates.legendaire = leg; }
