// compte ouvert dans un autre navigateur ou sur un autre appareil : cette page se met en pause
function blockElsewhere() {
    tabBlocked = true; M = null; clearTimeout(NET.timer);
    let o = byId('tab-block'); if (!o) { o = document.createElement('div'); o.id = 'tab-block'; document.body.appendChild(o); }
    o.innerHTML = `<div class="tb-box glass"><h2>Partie ouverte ailleurs</h2><p>Ton compte <b>${esc(profiles.active || '')}</b> vient d’être ouvert dans un autre navigateur, une fenêtre privée ou sur un autre appareil. Cette page est mise en pause pour protéger ta sauvegarde : une seule page de jeu à la fois.</p><button class="big-btn green" onclick="location.reload()">Jouer ici</button></div>`;
}
function blockTab() {
    tabBlocked = true; M = null;
    let o = byId('tab-block'); if (!o) { o = document.createElement('div'); o.id = 'tab-block'; document.body.appendChild(o); }
    o.innerHTML = `<div class="tb-box glass"><h2>Partie ouverte ailleurs</h2><p>Ton compte <b>${esc(profiles.active || '')}</b> vient d’être ouvert dans un autre onglet. Cet onglet est mis en pause pour protéger ta sauvegarde.</p><button class="big-btn green" onclick="location.reload()">Jouer dans cet onglet</button></div>`;
}
// une autre fenêtre (ou un autre joueur de l'appareil) a modifié ta sauvegarde : on la recharge
function externalSaveChange() {
    if (tabBlocked || !profiles.active) return;
    if (M && !M.over) { extReload = true; return; }
    loadState(profiles.active); updateHUD(); const v = currentView(); if (v === 'songe') renderSonges(); else if (v === 'shop') renderShop(); else if (v === 'accueil') renderAccueil(); else if (v === 'inventaire') renderInventaire();
}

