const MEM = {};
// ---------- Sécurité : les données importantes sont signées ----------
// Une sauvegarde, un rôle, un mute, une offre d'HDV… modifiés à la main (outils du navigateur) ne sont plus acceptés :
// le jeu reprend automatiquement la dernière version valide.
const RAW = {
    get(k) { try { return localStorage.getItem(k); } catch (e) { return MEM[k] ?? null; } },
    set(k, v) { try { localStorage.setItem(k, v); } catch (e) { MEM[k] = v; } },
    keys() { try { return Object.keys(localStorage); } catch (e) { return Object.keys(MEM); } }
};
