    state.collection = [];
    coll0.forEach(id => { if (cardById(id)) state.collection.push(id); else if (!unkC.includes(id)) unkC.push(id); });
    unkC.forEach(id => { if (cardById(id) && !state.collection.includes(id)) state.collection.push(id); });
    state.unk.cards = unkC.filter(id => !cardById(id));
    Object.keys(state.equip).forEach(sl => { const id = state.equip[sl]; if (!ITEMS[id]) { if (typeof id === 'string' && id) unkE[sl] = id; delete state.equip[sl]; } });
    Object.keys(unkE).forEach(sl => { const id = unkE[sl]; if (ITEMS[id]) { if (!state.equip[sl]) state.equip[sl] = id; else state.items[id] = (state.items[id] || 0) + 1; delete unkE[sl]; } });
