    if (profiles.list.length >= 1 && !founderDevice()) return toast(`Un seul compte par appareil : ton compte est « ${profiles.list[0].pseudo} ». Connecte-toi avec lui.`, 'err');
    if (discordPending) {   // compte Discord : pas de mot de passe (connexion par le bouton Discord)
        if (profiles.list.some(p => p.discordId === discordPending.id)) return toast('Ce compte Discord a déjà un compte Krosmofus.', 'err');
        const secret = [...crypto.getRandomValues(new Uint8Array(24))].map(b => b.toString(16).padStart(2, '0')).join('');
        profiles.list.push({ pseudo, classe: selectedClass, created: Date.now(), discordId: discordPending.id, pwHash: await hashPw(pseudo, secret), ...(refCode ? { refPending: refCode } : {}) });
        discordPending = null; saveProfiles(); authMode = 'login'; return login(pseudo);
    }
    if (pw.length < 4) return toast('Mot de passe : 4 caractères minimum.', 'err');
    if (pw !== pw2) return toast('Les deux mots de passe ne sont pas identiques.', 'err');
    const migrated = profiles.list.length === 0 && migrateOldSave(pseudo);
    profiles.list.push({ pseudo, classe: selectedClass, created: Date.now(), pwHash: await hashPw(pseudo, pw), ...(refCode ? { refPending: refCode } : {}) });
    saveProfiles();
