    if (!profiles.active && view !== 'accueil') { toast('Connecte-toi d’abord sur l’Accueil !', 'err'); view = 'accueil'; }
    if (profiles.active && state && state.welcomePack) { openWelcomePack(); if (view !== 'accueil') return; }   // d'abord le pack de démarrage
