    document.querySelectorAll('.nav-btn').forEach(b => b.classList.toggle('active', b.dataset.view === view));
    document.getElementById(`view-${view}`).classList.add('active');
    if (window.innerWidth <= 640 && view !== currentViewPrev) { try { window.scrollTo(0, 0); } catch (e) {} }
    currentViewPrev = view;
    setTimeout(() => musicForView(view), 0);
    document.body.className = 'bg-' + view;
    ({ accueil: renderAccueil, songe: renderSonges, inventaire: renderInventaire, shop: renderShop, koli: renderKoli, leaderboard: renderLeaderboard, updates: renderUpdates, admin: renderAdmin })[view]();
