        const el = document.createElement('div'); el.id = 'kf-dialog';
        el.innerHTML = `<div class="kd-box glass"><div class="kd-msg">${esc(msg)}</div>${input != null ? `<input class="kd-in" maxlength="24" value="${esc(input)}">` : ''}
            <div class="kd-btns"><button class="ghost kd-no">${esc(cancel)}</button><button class="${danger ? 'red' : 'green'} kd-yes">${esc(ok)}</button></div></div>`;
        document.body.appendChild(el);
