        const end = v => { el.remove(); document.removeEventListener('keydown', key); res(v); };
        const key = e => { if (!e.isTrusted) return; if (e.key === 'Escape') end(input != null ? null : false); if (e.key === 'Enter') end(input != null ? inp.value : true); };
        el.querySelector('.kd-yes').addEventListener('click', e => { if (e.isTrusted) end(input != null ? inp.value : true); });
