    if (mine.length) { NET.merging = true; try { mine.forEach(g => g.r ? mtAdd(g.r, Math.max(1, Math.min(10, +g.n || 1))) : addCard0(g.id, !!g.k)); } finally { NET.merging = false; } saveGame(); cloudDirty = true; }
