function maxCopies(id) { if (isHoloId(id)) return holoOwned(holoBase(id)) > 0 && cardById(id) ? 1 : 0; const c = cardById(id); const owned = countIds(state.collection)[id] || 0; return c ? Math.min(owned, CONFIG.MAX_COPIES[c.rarity] || 1) : 0; }
