// Force réelle des cartes (taux de victoire mesuré en simulation, un deck moyen + la carte) : sert au deck automatique
const CARD_RATING = { c_0: 49, c_1: 19, c_10: 7, c_11: 16, c_12: 23, c_13: 16, c_14: 26, c_15: 37, c_16: 10, c_17: 27, c_2: 17, c_3: 16, c_4: 21, c_5: 10, c_6: 19, c_7: 41, c_8: 14, c_9: 11, l1: 43, l2: 73, l3: 33, l4: 41, l5: 50, l6: 62, l7: 38, l8: 31, l9: 64, m_0: 13, m_1: 19, m_10: 33, m_11: 14, m_12: 17, m_13: 21, m_2: 11, m_3: 0, m_4: 17, m_5: 26, m_6: 14, m_7: 20, m_8: 10, m_9: 20, s_0: 14, s_1: 16, s_10: 7, s_11: 9, s_12: 21, s_13: 12, s_14: 14, s_15: 17, s_16: 14, s_2: 17, s_3: 6, s_4: 24, s_5: 20, s_6: 9, s_7: 20, s_8: 10, s_9: 27, fa86: 15, fa73: 15, fa74: 15, fa75: 15, fa76: 11, fa87: 19, fa88: 28, mo77: 17, mo78: 34, mo79: 27, mo80: 34, mo81: 27, mo82: 34, mo83: 23, mo84: 30, mo85: 57 };   // familiers et montures : mesurés en E0 (même échelle)
