function deckFromCode(txt) { const m = String(txt || '').trim().match(/KFD-([A-Za-z0-9+/]+)/); if (!m) return null; try { return atob(m[1] + '='.repeat((4 - m[1].length % 4) % 4)).split(',').filter(Boolean).slice(0, 60); } catch (e) { return null; } }
