function guardianFor(floor, noAdapt = false) {
    const boss = floor % CONFIG.BOSS_EVERY === 0;
    const g = boss ? bossAt(floor) : guardianAt(floor);
    const G = CONFIG.GUARD;
    const easy = Math.max(0, CONFIG.EASY_FLOORS + 5 - floor) * 0.4;   // jusqu'à -6 PV aux premiers étages, puis s'efface
    const ad = state && !noAdapt && CONFIG.ADAPT.enabled ? adaptFor(floor) : { pv: 0, bonus: 0, form: 0 };   // difficulté fixe : pas d'adaptation
    const late = Math.max(0, floor - G.lateFrom);
    const pv = Math.max(8, Math.min(G.pvMax, Math.round(G.pvBase + floor * G.pvPerFloor - easy)) + Math.round(late * G.latePv) + (boss ? G.bossPv : 0) + ad.pv);
    const tier = Math.floor(floor / CONFIG.BOSS_EVERY) * CONFIG.BOSS_EVERY;   // palier : la force des créatures monte à chaque boss, puis reste stable 5 étages
    const bonus = Math.max(0, Math.round((Math.min(G.bonusMax, tier / G.bonusEvery) + Math.max(0, tier - G.lateFrom) * G.lateBonus + ad.bonus) * 10) / 10);
    return { ...g, boss, pv, bonus: boss ? Math.max(0, Math.round((bonus - 0.3) * 10) / 10) : bonus, adapt: ad };   // 0.9.5 : créatures des boss un peu moins renforcées
}
const FLOOR_KAMAS = [51, 69];   // toute victoire hors boss : entre 51 et 69 Kamas au hasard, quel que soit l'étage (bonus compris)
const floorKamasRoll = () => FLOOR_KAMAS[0] + Math.floor(Math.random() * (FLOOR_KAMAS[1] - FLOOR_KAMAS[0] + 1));
function kamasFor(floor) { const K = CONFIG.KAMAS_CURVE; return Math.min(K.max, Math.round(K.base + K.perFloor * Math.max(1, floor))); }
// Kamas d'un boss des Songes : voir bossBonusRange (selon l'étage)
// défaite : entre 19 et 36 Kamas au hasard (bonus compris)
const LOSS_KAMAS = [19, 36];
const lossKamasRoll = () => LOSS_KAMAS[0] + Math.floor(Math.random() * (LOSS_KAMAS[1] - LOSS_KAMAS[0] + 1));
// boss des Songes : Kamas d'une victoire (51 à 69) + un bonus de boss qui monte avec l'étage
//   repères fixés : étage 5 → +15 à +24 · 10 → +24 à +25 · 15 → +26 à +32 · 20 → +33 à +37 · 100 → +74 à +84 (montée régulière entre 20 et 100) · après 100 : +74 à +89
const BOSS_BONUS_PTS = [[5, 15, 24], [10, 24, 25], [15, 26, 32], [20, 33, 37], [100, 74, 84]];
const BOSS_BONUS_AFTER = [74, 89];
function bossBonusRange(floor) {
    if (floor > 100) return BOSS_BONUS_AFTER;
    const P = BOSS_BONUS_PTS; if (floor <= P[0][0]) return [P[0][1], P[0][2]];
    for (let i = 1; i < P.length; i++) if (floor <= P[i][0]) { const [f0, a0, b0] = P[i - 1], [f1, a1, b1] = P[i], t = (floor - f0) / (f1 - f0); return [Math.round(a0 + t * (a1 - a0)), Math.round(b0 + t * (b1 - b0))]; }
    return [P[P.length - 1][1], P[P.length - 1][2]];
}
const BOSS_KAMAS = [67, 78];   // boss des Songes : 67 à 78 Kamas à tous les étages (avant série et Énutrof)
function bossKamasRange(floor) { return BOSS_KAMAS; }
const rollIn = ([a, b]) => a + Math.floor(Math.random() * (b - a + 1));
function bossKamasBonus(floor) { return rollIn(bossKamasRange(floor)); }
function streakBonus(n) { const t = CONFIG.WIN_STREAK.tiers.find(([w]) => n >= w); return t ? t[1] : 0; }
// XP adaptée au niveau : une victoire ≈ un niveau quand tu es au niveau visé de l'étage, davantage si tu es en retard
