        const c = pickWeighted(pool, ST.w);
        if (cnt[c.id] || deck.some(x => x.nom === c.nom)) continue;   // 0.9.8 : l'adversaire n'a jamais deux fois la même carte
        if (c.type === 'Sort' && deck.filter(x => x.type === 'Sort').length >= maxSpells) continue;
