    if (!fi.open) return toast(`Le prochain boss flash apparaît dans ${fmtClock(fi.nextIn)}.`, 'err');
    if (!fi.triesLeft) return toast('Tu as déjà affronté ce boss flash. Rendez-vous au prochain !', 'err');
    if (curDeck().length !== CONFIG.DECK_SIZE) return toast('Ton deck est incomplet.', 'err');
    const E = CONFIG.ENERGY;
    if (E.enabled && syncEnergy() < E.cost) return toast(`Il faut ${E.cost} énergie pour affronter le boss flash : +1 dans ${fmtClock(energyLeft())}.`, 'err');
