//  EXTENSIONS
// =====================================================================
function validateCard(c, i) {
    const label = c && c.nom ? `"${c.nom}"` : `n°${i + 1}`;
    if (!c || typeof c !== 'object') return `Carte n°${i + 1} : ce n'est pas un objet.`;
    if (!c.id || !/^[\w-]+$/.test(c.id)) return `Carte ${label} : "id" obligatoire (lettres, chiffres, - et _).`;
    if (!c.nom) return `Carte n°${i + 1} : "nom" obligatoire.`;
    if (cardById(c.id)) return `Carte ${label} : l'id "${c.id}" existe déjà.`;
    if (!RARITY_ORDER.includes(c.rarity)) return `Carte ${label} : rarity doit être ${RARITY_ORDER.join(', ')}.`;
    if (!TYPES.includes(c.type)) return `Carte ${label} : type doit être ${TYPES.join(', ')}.`;
    if (typeof c.pa !== 'number' || c.pa < 0 || c.pa > 10) return `Carte ${label} : "pa" doit être un nombre entre 0 et 10.`;
    if (c.type !== 'Sort' && (typeof c.atk !== 'number' || typeof c.pv !== 'number' || c.pv < 1)) return `Carte ${label} : une créature a besoin de "atk" et "pv" (nombres, pv ≥ 1).`;
    if (c.kw && (!Array.isArray(c.kw) || c.kw.some(k => !KW[k]))) return `Carte ${label} : mots-clés possibles : ${Object.keys(KW).join(', ')}.`;
    for (const field of ['cri', 'souffle', 'effets']) {
        if (c[field] === undefined) continue;
        if (!Array.isArray(c[field])) return `Carte ${label} : "${field}" doit être une liste.`;
        for (const e of c[field]) {
            if (!e || !FX[e.fx]) return `Carte ${label} : effet inconnu dans "${field}". Effets possibles : ${Object.keys(FX).join(', ')}.`;
            if (e.fx === 'summon' && !TOKENS[e.token]) return `Carte ${label} : token inconnu (${Object.keys(TOKENS).join(', ')}).`;
            if (e.fx === 'giveKwAll' && !KW[e.kw]) return `Carte ${label} : mot-clé inconnu pour giveKwAll.`;
        }
    }
    return null;
}
function injectExtension() {
    if (!isFounder()) return deny();
    let parsed;
    try { parsed = JSON.parse(document.getElementById('json-injector').value.trim()); }
    catch (e) { return toast('Erreur de syntaxe JSON : vérifie virgules, guillemets et crochets.', 'err'); }
    if (!Array.isArray(parsed)) return toast('Le JSON doit être une liste : [ { ... } ]', 'err');
    for (let i = 0; i < parsed.length; i++) { const err = validateCard(parsed[i], i); if (err) return toast('' + err, 'err'); }
    const ext = extLoad().filter(c => !parsed.some(p => p.id === c.id)).concat(parsed); LS.set(EXT_KEY, JSON.stringify(ext));
    addCardsToPool(parsed); saveGame(); renderUpdates();
    toast(`Extension déployée : ${parsed.length} carte(s) ajoutée(s) aux boosters de tous les comptes de cet appareil. Pour les autres joueurs, intègre-les dans une nouvelle version du jeu.`);
}
