function changelogHTML() {
    return `<div class="patch-note-card glass changelog"><strong>Notes de mise à jour</strong>${CHANGELOG.map(c => `<div class="cl-entry"><div class="cl-head"><b>${esc(c.v)}</b><small>${esc(c.date)}</small></div><ul>${c.items.map(i => `<li>${esc(i)}</li>`).join('')}</ul></div>`).join('')}</div>`;
}
function renderUpdates() {
    const ex = `[
  { "id": "x1", "nom": "Comte Harebourg", "type": "Monstre", "rarity": "legendaire",
    "pa": 7, "atk": 6, "pv": 7, "emo": "", "kw": ["provoc"],
    "cri": [{ "fx": "freezeAll" }], "img": "" }
]`;
    const fxHelp = Object.keys(FX).map(k => `<div><code>${k}</code> — ${esc(FX[k].txt({ n: 'n', m: 'm', atk: 'a', pv: 'p', token: 'tofu', kw: 'chance', count: 1 }, true))}</div>`).join('');
    document.getElementById('view-updates').innerHTML = `
        <h2 class="gold">${isFounder() ? 'Krosmofus Dev Studio — Extensions' : 'Extensions'}</h2>
        ${adminPanelHTML()}
        ${isFounder() ? `<div class="patch-note-card glass">
            <strong>Publier un patch de cartes</strong>
            <p>Colle tes nouvelles cartes au format JSON : elles rejoignent immédiatement les boosters.</p>
            <textarea id="json-injector" spellcheck="false">${esc(ex)}</textarea>
            <button onclick="injectExtension()" style="margin-top:10px;">Déployer la mise à jour</button>
            <details style="margin-top:12px; font-size:12px;"><summary style="cursor:pointer;">Aide : champs, mots-clés et effets</summary>
                <p>Champs : <code>id</code>, <code>nom</code>, <code>type</code> (Héros / Monstre / Sort), <code>rarity</code> (commun / rare / epique / legendaire), <code>pa</code>, <code>atk</code>, <code>pv</code> (créatures), <code>emo</code>, <code>img</code>, <code>kw</code>, <code>cri</code>, <code>souffle</code>, <code>effets</code> (sorts).</p>
                <p>Mots-clés (<code>kw</code>) : ${Object.keys(KW).map(k => `<code>${k}</code>`).join(', ')} · Tokens (<code>summon</code>) : ${Object.keys(TOKENS).map(k => `<code>${k}</code>`).join(', ')}</p>
                <div class="help-table">${fxHelp}</div>
            </details>
        </div>` : ''}
        ${isFounder() ? `<div class="version-tag">Krosmofus TCG — ${esc(CONFIG.VERSION)}</div>` : ''}`;
}

// =====================================================================
//  PERSONNAGE : CARACTÉRISTIQUES, ÉQUIPEMENTS, PANOPLIES, PASSIFS
// =====================================================================
const SLOTS = [
    { id: 'coiffe', nom: 'Coiffe', emo: '🎩' }, { id: 'cape', nom: 'Cape', emo: '🧥' }, { id: 'amulette', nom: 'Amulette', emo: '📿' },
    { id: 'anneau', nom: 'Anneau', emo: '💍' }, { id: 'anneau2', nom: 'Anneau 2', emo: '💍', ring2: true }, { id: 'ceinture', nom: 'Ceinture', emo: '🎗️' }, { id: 'bottes', nom: 'Bottes', emo: '👢' },
    { id: 'arme', nom: 'Arme', emo: '⚔️' }, { id: 'bouclier', nom: 'Bouclier', emo: '🛡️' },
    { id: 'familier', nom: 'Familier / Monture', emo: '🐾', pet: true },
    { id: 'trophee', nom: 'Trophée', emo: '🏆', trophySlot: true }   // va dans les 6 emplacements à œufs   // une carte Familier OU Monture de ta collection (comme dans Dofus)
];
// Caractéristiques façon Dofus et leur effet dans le TCG
const CARACS = {
    vita:   { nom: 'Vitalité',     icon: '❤️', color: '#fc8181', cost: 1, desc: v => `+${Math.floor(v / CONFIG.CARAC.vitaPerPv)} PV pour ton héros (${CONFIG.CARAC.vitaPerPv} points de Vitalité = 1 PV)` },
    sag:    { nom: 'Sagesse',      icon: '📘', color: '#b794f4', cost: 1, desc: v => `+${fmtPct(caracPct('sag', state, v))} % d’XP gagnée` },
    force:  { nom: 'Force',        icon: '🟫', color: '#c9965a', cost: 1, desc: v => `+${fmtPct(caracPct('force', state, v))} % de dégâts de tes créatures et aux sorts Terre et Neutre` },
    intel:  { nom: 'Intelligence', icon: '🔥', color: '#f6ad55', cost: 1, desc: v => `+${fmtPct(caracPct('intel', state, v))} % aux sorts Feu, aux soins, aux Cris et Derniers souffles` },
    chance: { nom: 'Chance',       icon: '💧', color: '#63b3ed', cost: 1, desc: v => `+${fmtPct(dropPctOf(state, v))} % de drop · +${fmtPct(caracPct('chance', state, v))} % aux sorts Eau` },
    agi:    { nom: 'Agilité',      icon: '🌪️', color: '#68d391', cost: 1, desc: v => `${fmtPct(caracPct('agi', state, v))} % d’esquive sur ton héros · +${fmtPct(caracPct('agi', state, v))} % aux sorts Air` }
};
// Barème des caractéristiques : un point de capital vaut plus qu'une stat d'équipement
const r1 = v => Math.round(v * 10) / 10;
// pourcentage de drop lisible : 0,33 % · 1,65 % · 12 %
// chances de drop selon l'étage
const dropFloorMult = f => { const t = CONFIG.ENDGAME_DROP.find(([from]) => (f || 0) >= from); return t ? t[1] : 1; };
const bossCardChance = f => { const B = CONFIG.BOSS_CARD_DROP; return (f || 0) >= B.from ? B.high : B.low; };
const dofusChance = () => 0;   // 0.9.5 : plus de Dofus au hasard sur les boss
// Dofus exclusifs : chaque Dofus tombe sur ses boss (étage 75 et plus, 0,09 %) ; leur booster de boss peut aussi le contenir (0,1 %)
const BOSS_DOFUS = { 'Chêne Mou': 'l7', 'Dragon Cochon': 'l7', 'Minotoror': 'l8', 'Minotot': 'l8', 'Dark Vlad': 'l5', 'Crocabulia': 'l6', 'Tal Kasha': 'l9', 'Rat Noir': 'l15', 'Wa Wabbit': 'l16' };
const bossDofusOf = (nom, f) => BOSS_DOFUS[nom] && (f || 0) >= CONFIG.DOFUS_DROP.minFloor ? BOSS_DOFUS[nom] : null;
const songeDofusOk = f => (f || 0) >= 100;   // Dofus des Songes : n'importe quel boss des Songes, étage 100 et plus
const legItemPool = () => ALL_CARDS.filter(c => c.exclusive === 'legdrop');
const wildItemChance = d => ITEMS[d.id] && ITEMS[d.id].stats.pa ? d.chance : Math.max(d.chance, CONFIG.WILD.itemChance);   // boss flash : 1,5 % par pièce, sauf les objets à PA
function endgameTag(f) { const m = dropFloorMult(f); return m > 1 ? `<span class="drop-bonus" style="margin-left:6px" title="Bonus de fin de jeu sur toutes les chances de drop">🚀 +${Math.round((m - 1) * 100)} % de drop (étage ${f})</span>` : ''; }
function dropFmt(v) { const p = Math.min(100, v * 100), d = p < 1 ? 2 : p < 10 ? 2 : 1; return String(Math.round(p * 10 ** d) / 10 ** d).replace('.', ',') + ' %'; }
function dropBonusTag(dp) { return `<span class="drop-bonus ${dp > 0 ? '' : 'off'}" title="Ta Chance (capital et équipement) et ton passif augmentent toutes les chances de drop">${dp > 0 ? `+${fmtPct(dp)} % de drop inclus` : 'Monte ta Chance pour plus de drop'}</span>`; }
const fmtPct = v => String(r1(v)).replace('.', ',');
function caracPct(k, st = state, total) {
    const base = n((st.carac || {})[k]), all = total != null ? total : playerStats(st)[k], gear = Math.max(0, all - base), C = CONFIG.CARAC;
    return r1(base * C.ptPct + gear * C.gearPct);
}
// Barème affiché sous chaque caractéristique
function caracRate(k) {
    const C = CONFIG.CARAC, f = v => String(Math.round(v * 100) / 100).replace('.', ','), cap = C.ptPct * 10, gear = C.gearPct * 20;
    if (k === 'vita') return `+${C.vitaPerPv} points = +1 PV (capital ou équipement)`;
    if (k === 'chance') return `+10 points de capital = +${f(C.ptDrop * 10)} % de drop et +${f(cap)} % Eau · équipement : +20 = +${f(C.gearDrop * 20)} % de drop et +${f(gear)} % Eau`;
    const what = { sag: 'd’XP', force: 'de dégâts', intel: 'Feu et soins', agi: 'd’esquive et Air' }[k] || '';
    return `+10 points de capital = +${f(cap)} % ${what} · équipement : +20 = +${f(gear)} %`;
}
// % de drop : Chance investie + Chance des Dofus équipés (l'équipement ne compte plus) ; taux final = taux de base × (1 + bonus / 100)
function dropPctOf(st = state, total) {
    const base = n((st.carac || {}).chance), dof = TROPHY_SLOTS.reduce((t, sl) => { const it = ITEMS[(st.equip || {})[sl]]; return t + (it && it.cardId && DOFUS_FX[it.cardId] ? n(it.stats.chance) : 0); }, 0);
    return r1((base + dof) * CONFIG.CARAC.ptDrop);
}
// Résistances élémentaires : uniquement sur certains objets (non modifiables), réduisent les dégâts des sorts adverses de cet élément
const RESISTS = {
    rTerre: { nom: 'Résistance Terre', el: 'force', color: '#c9965a' }, rFeu: { nom: 'Résistance Feu', el: 'intel', color: '#f6ad55' },
    rEau: { nom: 'Résistance Eau', el: 'chance', color: '#63b3ed' }, rAir: { nom: 'Résistance Air', el: 'agi', color: '#68d391' }
};
const statNom = k => k === 'pa' ? 'PA' : RESISTS[k] ? RESISTS[k].nom : (CARACS[k] || { nom: k }).nom;
const statColor = k => RESISTS[k] ? RESISTS[k].color : (CARACS[k] || { color: '#fff' }).color;
const statVal = (k, v) => RESISTS[k] ? `+${v} %` : `+${v}`;
// Panoplies : où elles tombent, niveau, éléments et pièces
