function checkTrophies(silent) {
    if (!state) return; const seen = state.troSeen = state.troSeen || [];
    TROPHIES.forEach(t => { if (!seen.includes(t.id) && t.ok(state)) { seen.push(t.id); if (!silent) setTimeout(() => toast(`🏆 ${t.nom} débloqué ! Équipe-le dans un emplacement à œuf (Inventaire › Équipement).`), 1500); } });
}
function trophyOwned(id, st = state) {
    const it = ITEMS[id]; if (!it || !it.trophy) return false;
    if (it.bag) return (st.items || {})[id] > 0 || TROPHY_SLOTS.some(s => (st.equip || {})[s] === id);
    if (it.cardId) return (st.collection || []).includes(it.cardId);
    const t = TROPHIES.find(x => x.id === id); return !!(t && t.ok(st));
}
