let invTab = 'equip', bagFilter = 'all';
const INV_TABS = [['equip', `<img class="bag-img" src="${ASSET_BAG}" alt=""> Équipement`], ['decks', 'Decks'], ['compos', 'Compos'], ['collection', 'Collection'], ['quetes', 'Quêtes<span id="quest-dot" class="q-dot"></span>']];
function goMyBoosters() { shopTab = 'mine'; setView('shop'); }
function setFarmFloor(v) { v = Math.floor(+v) || 0; farmFloor = v > 0 && state && v < state.floor ? v : 0; renderSonges(); }
function autoDeckActive() { autoDeck(state.activeDeck); renderSonges(); }
function editActiveDeck() { editDeck = state.activeDeck; openInv('decks'); }
function openInv(tab) { if (tab === 'hdv') return openHdv(); invTab = tab; setView('inventaire'); }
// L'hôtel de vente est dans la Boutique (onglet « Hôtel de vente »)
function openHdv(preset = '') { hdvPreset = preset; shopTab = 'hdv'; setView('shop'); }
function setInvTab(t) { invTab = t; renderInventaire(); }
// =====================================================================
//  BANQUE : cartes et objets rangés à l'abri, communs à tes personnages. Ouverture payante au-delà de 15 objets rangés.
// =====================================================================
const BANK_SVG = `<svg class="bank-ico" viewBox="0 0 64 64" aria-hidden="true"><defs><linearGradient id="bkG" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff3b0"/><stop offset="0.55" stop-color="#e2a52c"/><stop offset="1" stop-color="#8a5a12"/></linearGradient></defs>
    <path d="M32 4 L60 18 L60 24 L4 24 L4 18 Z" fill="url(#bkG)" stroke="#3a2506" stroke-width="2.4" stroke-linejoin="round"/><circle cx="32" cy="16" r="4.6" fill="#fff8d6" stroke="#3a2506" stroke-width="1.8"/>
    <g fill="url(#bkG)" stroke="#3a2506" stroke-width="2"><rect x="9" y="27" width="7" height="22" rx="1.5"/><rect x="21" y="27" width="7" height="22" rx="1.5"/><rect x="36" y="27" width="7" height="22" rx="1.5"/><rect x="48" y="27" width="7" height="22" rx="1.5"/></g>
    <path d="M3 52 H61 V59 H3 Z" fill="url(#bkG)" stroke="#3a2506" stroke-width="2.4" stroke-linejoin="round"/></svg>`;
const BANK_FEES = [[100, 2000], [50, 1700], [30, 1350], [15, 1000]];   // plus de 100 objets rangés : 2 000 Kamas l'ouverture, etc. ; 15 ou moins : gratuit
function bankData() { if (!state) return { items: {}, cards: {} }; const b = state.bank = state.bank && typeof state.bank === 'object' ? state.bank : {}; b.items = b.items || {}; b.cards = b.cards || {}; return b; }
function bankCount() { const b = bankData(); return [...Object.values(b.items), ...Object.values(b.cards)].reduce((t, v) => t + (+v > 0 ? +v : 0), 0); }
function bankFee(nb = bankCount()) { const f = BANK_FEES.find(([m]) => nb > m); return f ? f[1] : 0; }
let bankOpen = false, bankTab = 'items', bankQ = '';
function setBankTab(t) { bankTab = t === 'cards' ? 'cards' : 'items'; renderBank(); }
function setBankQ(v) { bankQ = String(v || '').slice(0, 40); renderBank(); const el = byId('bank-q'); if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }
async function openBank() {
    if (!state) return; if (fightOn()) return toast('Termine ton combat avant d’aller à la banque.', 'err');
    const nb = bankCount(), fee = bankFee(nb);
    if (!bankOpen && fee) {
        if (kamasLow(fee)) return toast(`Ouvrir la banque coûte ${fee.toLocaleString('fr-FR')} Kamas (${nb} objets rangés).`, 'err');
        if (!(await askConfirm(`Ouvrir la banque pour ${fee.toLocaleString('fr-FR')} Kamas ? Tu y as rangé ${nb} objets (plus de 15 : l’ouverture est payante).`, { ok: 'Payer et ouvrir' })) || !state || kamasLow(fee)) return;
        state.kamas -= fee; saveGame(); updateHUD();
    }
    bankOpen = true; renderBank(); byId('bank-modal').classList.add('open');
}
function closeBank() { bankOpen = false; closeModal('bank-modal'); if (currentView() === 'inventaire') renderInventaire(); }
function bankMatch(nom) { const w = normTxt(bankQ).trim().split(/\s+/).filter(Boolean); return !w.length || w.every(t => normTxt(nom).includes(t)); }
function bankRow(icon, nom, sub, n, act) { return `<div class="bk-row">${icon}<div class="bk-txt"><b>${nom}</b><small>${sub}</small></div>${n > 1 ? `<span class="chip">×${n}</span>` : ''}<div class="bk-act">${act}</div></div>`; }
function renderBank() {
    const b = bankData(), nb = bankCount(), fee = bankFee(nb), m = byId('bank-modal');
    const cardIco = c => `<span class="dl-ico card-mini r-${c.rarity}" data-tip="card:${c.id}">${c.img ? `<img src="${c.img}" alt="">` : esc(c.emo)}</span>`;
    let mine = '', bank = '';
    if (bankTab === 'items') {
        mine = Object.entries(state.items).filter(([id, n]) => n > 0 && ITEMS[id] && bankMatch(ITEMS[id].nom)).sort((x, y) => ITEMS[y[0]].lvl - ITEMS[x[0]].lvl).map(([id, n]) => { const it = ITEMS[id];
            return bankRow(itemIcon(it), `<span style="color:${it.color}">${esc(it.nom)}</span>`, `Niv. ${it.lvl}`, n, `<button class="mini" onclick="bankPut('item','${id}',1)">Ranger</button>${n > 1 ? `<button class="ghost mini" onclick="bankPut('item','${id}',${n})">Tout</button>` : ''}`); }).join('');
        bank = Object.entries(b.items).filter(([id, n]) => n > 0 && ITEMS[id] && bankMatch(ITEMS[id].nom)).map(([id, n]) => { const it = ITEMS[id];
            return bankRow(itemIcon(it), `<span style="color:${it.color}">${esc(it.nom)}</span>`, `Niv. ${it.lvl}`, n, `<button class="mini green" onclick="bankTake('item','${id}',1)">Prendre</button>${n > 1 ? `<button class="ghost mini" onclick="bankTake('item','${id}',${n})">Tout</button>` : ''}`); }).join('');
    } else {
        const own = [...new Set(state.collection)].map(cardById).filter(c => c && !isGear(c) && lastCopySellable(c) && bankMatch(c.nom));
        mine = own.sort((x, y) => RARITY_ORDER.indexOf(y.rarity) - RARITY_ORDER.indexOf(x.rarity) || x.nom.localeCompare(y.nom)).map(c => { const d = state.dupes[c.id] || 0;
            return bankRow(cardIco(c), esc(c.nom), `${RARITY_LABEL[c.rarity]}${d ? ` · ${d} doublon${d > 1 ? 's' : ''}` : ' · seul exemplaire'}`, d + 1, `<button class="mini" onclick="bankPut('card','${c.id}',1)">Ranger</button>${d > 1 ? `<button class="ghost mini" onclick="bankPut('card','${c.id}',${d})" title="Ranger tous les doublons">Doublons</button>` : ''}`); }).join('');
        bank = Object.entries(b.cards).filter(([id, n]) => n > 0 && cardById(id) && bankMatch(cardById(id).nom)).map(([id, n]) => { const c = cardById(id);
            return bankRow(cardIco(c), esc(c.nom), RARITY_LABEL[c.rarity], n, `<button class="mini green" onclick="bankTake('card','${id}',1)">Prendre</button>${n > 1 ? `<button class="ghost mini" onclick="bankTake('card','${id}',${n})">Tout</button>` : ''}`); }).join('');
    }
    m.innerHTML = `<div class="glass bank-box"><div class="bk-head">${BANK_SVG}<div><h2>Banque</h2><small>Commune à tes personnages · ${nb} objet${nb > 1 ? 's' : ''} rangé${nb > 1 ? 's' : ''} · prochaine ouverture : ${fee ? fee.toLocaleString('fr-FR') + ' Kamas' : 'gratuite'}</small></div><button class="ghost" onclick="closeBank()">Fermer</button></div>
        <div class="bk-tools"><div class="sub-tabs"><button class="${bankTab === 'items' ? 'on' : 'ghost'}" onclick="setBankTab('items')">Objets</button><button class="${bankTab === 'cards' ? 'on' : 'ghost'}" onclick="setBankTab('cards')">Cartes</button></div>
            <input id="bank-q" type="search" placeholder="Rechercher…" value="${esc(bankQ)}" oninput="setBankQ(this.value)"></div>
        <div class="bk-cols"><div class="bk-col"><h3>${esc(currentProfile().pseudo)} · ${bankTab === 'items' ? 'Sac' : 'Collection'}</h3><div class="bk-list">${mine || '<p class="coll-hint">Rien à ranger ici.</p>'}</div></div>
            <div class="bk-col"><h3>Banque</h3><div class="bk-list">${bank || '<p class="coll-hint">La banque est vide.</p>'}</div></div></div>
        <small class="bk-note">Ouverture gratuite jusqu’à 15 objets rangés, puis 1 000 Kamas (plus de 15), 1 350 (plus de 30), 1 700 (plus de 50) et 2 000 (plus de 100). Les objets équipés restent sur toi.</small></div>`;
}
async function bankPut(kind, id, nb) {
    if (!state || !bankOpen) return; nb = Math.max(1, Math.floor(+nb) || 1); const b = bankData();
    if (kind === 'item') { const have = state.items[id] || 0; if (!ITEMS[id] || have < 1) return; nb = Math.min(nb, have); state.items[id] = have - nb; if (!state.items[id]) delete state.items[id]; b.items[id] = (b.items[id] || 0) + nb; }
    else {
        const c = cardById(id); if (!c || isGear(c) || !lastCopySellable(c) || !state.collection.includes(id)) return; const d = state.dupes[id] || 0;
        if (d >= 1) { nb = Math.min(nb, d); state.dupes[id] = d - nb; if (!state.dupes[id]) delete state.dupes[id]; }
        else {   // seul exemplaire : il quitte la collection (et les decks, et l'emplacement à œuf pour un Dofus)
            if (!(await askConfirm(`C’est ton seul exemplaire de ${c.nom} : en le rangeant, il quitte ta collection${isDofusEquip(c) ? ' et tes emplacements à œuf' : ''} et tes decks. Continuer ?`, { ok: 'Ranger' })) || !state || !state.collection.includes(id) || (state.dupes[id] || 0) > 0) return;
            nb = 1; if (!dropLastCopy(id)) return;
        }
        b.cards[id] = (b.cards[id] || 0) + nb;
    }
    saveGame(); cloudNow(); renderBank();
}
function bankTake(kind, id, nb) {
    if (!state || !bankOpen) return; nb = Math.max(1, Math.floor(+nb) || 1); const b = bankData(), box = kind === 'item' ? b.items : b.cards, have = box[id] || 0; if (have < 1) return; nb = Math.min(nb, have);
    box[id] = have - nb; if (!box[id]) delete box[id];
    if (kind === 'item') state.items[id] = (state.items[id] || 0) + nb; else for (let i = 0; i < nb; i++) addCard(id, true);
    mergeSeen(); saveGame(); cloudNow(); renderBank();
}
