const OMEGA_ORN_LV = Object.keys(OMEGA_ORN).map(Number).sort((a, b) => a - b);
const OMEGA_FAM = [{ max: 75, nom: 'Bronze', col: '#e8a33a' }, { max: 175, nom: 'Émeraude', col: '#7ed321' }, { max: 275, nom: 'Pourpre', col: '#e0245e' }, { max: 375, nom: 'Cristal', col: '#5fe0e0' }, { max: 475, nom: 'Obsidienne', col: '#f6a623' }];
