    { cat: 'collection', id: 'col_e01', nom: 'Collectionneur glaçant', goal: 'Posséder toutes les cartes de l’extension Frigost (E01)', prog: st => { const L = ALL_CARDS.filter(c => c.ed === 'E01' && !isGear(c)), own = new Set(st.collection || []); return [L.filter(c => own.has(c.id)).length, L.length]; }, rew: { title: 'collec_e01' } },
    { cat: 'special', id: 'moisson', nom: 'L’Éternelle Moisson', goal: `Réunir les ${ARCHIS.length} archimonstres, les confier à l’Otomaï, puis vaincre le Kralamoure Géant (étage spécial des Songes)`, prog: st => st.moisson ? [ARCHIS.length, ARCHIS.length] : [archiOwned(st), ARCHIS.length], done: st => st.moisson === 'won', rew: { kamas: 5000, orn: 'moisson', title: 'moisson' } },
    { cat: 'special', id: 'godpack', nom: 'God Packer', goal: 'Ouvrir un God Pack (titre débloqué tout seul)', prog: st => [Math.min(1, st.godPacks || 0), 1], rew: { title: 'godpacker' } },
    { cat: 'special', id: 'frigost', nom: 'Maître de Frigost', goal: 'Réussir les Songes héroïques de Frigost (vaincre le Comte Harebourg à l’étage 50)', acct: true, prog: st => [st.frig && st.frig.wins > 0 ? 1 : 0, 1], rew: { kamas: 5000, xp: 2000000, title: 'frigost' } }
