const questDone = (q, st = state) => !q.soon && (q.done ? q.done(st) : (([a, b]) => a >= b)(q.prog(st)));
const questClaimed = (q, st = state) => !!(st && ((st.quests && st.quests[q.id]) || (q.acct && st.frig && st.frig.qc && st.frig.qc[q.id])));   // quête de compte (Frigost) : une seule fois pour tous les personnages
