    if (kamasLow(offer.price)) return toast(`Il te manque ${offer.price - state.kamas} Kamas.`, 'err');
    state.kamas -= offer.price; hdvLog('achat', offer, offer.price, '');
    if (offer.kind === 'card') addCard(offer.cardId, true);
    else hdvGive(offer);
    hdvSave(list.filter(o => o.key !== key));
