// prix plancher à l'HDV : cartes légendaires 12 000 Kamas, épiques 6 000 (vérifié aussi par le serveur)
const HDV_MIN = { legendaire: 12000, epique: 6000 };
const HDV_BOSS_MIN = 1000, HDV_FLAT_TAX = 1125;
function hdvMinPrice(kind, id) { const c = kind === 'card' ? cardById(id) : null; if (c && c.archi) return ARCHI_MIN[c.rarity] || 250; if (c && c.type === 'Boss') return HDV_BOSS_MIN; return c && HDV_MIN[c.rarity] || 1; }
