const offerChar = key => { const v = state && state.offerChar && state.offerChar[key]; return Array.isArray(v) ? v[0] : 0; };   // offres d'avant les personnages : 1er personnage
const myCharOffer = o => o.seller === profiles.active && offerChar(o.key) === (state.charIdx || 0);
