const KZT_ICO = () => `<img class="kzt-ico" src="${KOLI_ART.kzt}" alt="Kolizétons">`;
const RCOL = { commun: '#cbd5e0', rare: '#63b3ed', epique: '#b794f4', legendaire: '#f6ad55' };
const leagueOf = cote => [...LEAGUES].reverse().find(l => (+cote || 0) >= l.min) || LEAGUES[0];
const koliPlaced = p => !!p && (p.n != null ? p.n : (p.w || 0) + (p.l || 0)) >= KOLI.place;
const koliLeagueName = p => koliPlaced(p) ? leagueOf(p.cote).nom : 'Pas encore de ligue';
const gradeImg = (p, cls = '') => koliPlaced(p) ? `<img class="kz-grade ${cls}" src="${KOLI_ART.grade[leagueOf(p.cote).id]}" alt="${esc(leagueOf(p.cote).nom)}">` : `<span class="kz-grade none ${cls}">?</span>`;
