    if (r && r.ok) { KZ.me = r.me ? { ...r.me } : null; KZ.win = r.win || null; KZ.seasonEnd = r.seasonEnd || 0; KZ.last = r.last || null; setTimeout(trackKoliBest, 0); KZ.list = r.list || []; KZ.top = r.top || []; KZ.loaded = true; KZ.err = ''; }
    else KZ.err = (r && r.err) || 'Serveur injoignable.';
