            const prev = o.moisson ? `<span class="po-kz po-moisson" style="background-image:url('${OTOMAI_ART}')"></span>` : o.om ? `<span class="po-kz" style="background-image:url('${OMEGA_ORN[o.om].n}')"></span>` : o.kz || o.frame ? `<span class="po-kz" style="background-image:url('${o.kz ? KOLI_ART.orn[o.kz] : ORN_FRAME_200}')"></span>` : o.tier ? `<span class="orn orn-${o.tier}"><span class="av">${classAvatar(d.classe)}</span></span>` : o.id === 'none' ? `<span class="orn-none"><span class="av">${classAvatar(d.classe)}</span></span>` : `<span class="po-auto">Auto</span>`;
