        levain_givre: { nom: 'Levain de givre', img: 'levain_givre', kind: 'Produit du Boulanger', desc: 'Pour le fil de givre du Paysan et les holos du Cartomage.' },
        poudre_eclat: { nom: 'Poudre d’éclat', img: 'poudre_eclat', kind: 'Produit du Cartomage', desc: 'Faite avec des doublons de cartes. Pour la farine de givre et le bonbon arc-en-ciel.' },
