// =====================================================================
//  COMMANDES DU FONDATEUR (admin)
// =====================================================================
// Le rôle de fondateur ne s'obtient qu'avec la clé secrète du fondateur (seule son empreinte est dans le code).
// Les rôles sont signés et liés au mot de passe du compte : les modifier à la main ne donne aucun accès.
const FOUNDER_KEY_HASH = '963c815dd2f2efab91b18480eedbcf8bab5a4118a76942464c73555f3ce263fa';
const ROLES_KEY = 'krosmofus_roles';
function rolesLoad() { try { return JSON.parse(LS.get(ROLES_KEY)) || {}; } catch (e) { return {}; } }
