function roleOf(pseudo) {
    const p = pseudo && findProfile(pseudo); if (!p) return null;
    const r = rolesLoad()[p.pseudo.toLowerCase()];
    return r && r.sig === roleSig(p, r.role) ? r.role : null;
}
let roleGrant = false;
function setRole(pseudo, role) {
    const p = findProfile(pseudo); if (!p) return false;
    if (role === 'fondateur' && !roleGrant) return false;
    if (role !== 'fondateur' && !roleGrant && !isFounder()) return false;
    const r = rolesLoad(), k = p.pseudo.toLowerCase();
    if (role) r[k] = { role, sig: roleSig(p, role), t: Date.now() }; else delete r[k];
    LS.set(ROLES_KEY, JSON.stringify(r)); return true;
}
function isFounder(p = currentProfile()) { return !!p && roleOf(p.pseudo) === 'fondateur'; }
function isModo(p = currentProfile()) { return !!p && roleOf(p.pseudo) === 'modo'; }
