let founderTries = 0, founderLockUntil = 0;
async function claimFounder(key) {
    const p = currentProfile(); if (!p) return deny();
    if (Date.now() < founderLockUntil) return toast('Trop d’essais. Réessaie dans quelques minutes.', 'err');
    const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode('krosmofus-founder:' + (key || '').trim().toUpperCase()));
    const hex = [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('');
    if (hex !== FOUNDER_KEY_HASH) { if (++founderTries >= 5) { founderLockUntil = Date.now() + 10 * 60000; founderTries = 0; } return toast('Clé invalide.', 'err'); }
    const r = rolesLoad(); Object.keys(r).forEach(k => { if (r[k].role === 'fondateur') delete r[k]; }); LS.set(ROLES_KEY, JSON.stringify(r));   // un seul fondateur
    roleGrant = true; setRole(p.pseudo, 'fondateur'); roleGrant = false; LS.set(SRV_KEY, (key || '').trim().toUpperCase()); setTimeout(updateHUD, 0); toast(`Bienvenue ${p.pseudo} : tu es le fondateur de Krosmofus TCG. Tes commandes marchent aussi sur les joueurs en ligne.`);
    renderChat(); const v = currentView(); if (v === 'updates') renderUpdates(); if (v === 'accueil') renderAccueil();
}
