    if (normTxt(pseudo) === 'tous') return askConfirm(`Envoyer le pack de redémarrage (${starterLabel()}) à TOUS les joueurs du serveur ?`, { ok: 'Envoyer à tous' }).then(ok => { if (ok && !serverAdmin('giveall', '', 0, { g })) toast('Le serveur n’est pas joignable.', 'err'); });
    const t = adminTarget(pseudo); if (!t) return toast(`Joueur « ${pseudo} » introuvable.`, 'err');
