function findCardsByName(q) { const t = normTxt(q).trim(); if (!t) return []; const L = ALL_CARDS.filter(c => !c.custom); const ex = L.filter(c => normTxt(c.nom) === t); return ex.length ? ex : L.filter(c => normTxt(c.nom).includes(t)); }
