        let who = '', q = all; if (all.includes('>')) { const [a, b] = all.split('>').map(x => x.trim()); if (findCardsByName(a.replace(/\s*[x×]\d+$/i, '')).length && !findCardsByName(b.replace(/\s*[x×]\d+$/i, '')).length) { q = a; who = b; } else { who = a; q = b; } }
        const mq = q.match(/\s*[x×](\d+)$/i), nb = mq ? Math.max(1, Math.min(50, +mq[1])) : 1; if (mq) q = q.slice(0, mq.index).trim();
