function frigCloseRun() { const F = frigState(); if (!F || !F.run || !(F.run.dead || (F.run.won && !F.run.offer))) return; F.last = { floor: F.run.dead ? F.run.deathFloor : FRIG.floors, won: !!F.run.won, kdg: F.run.kdg, classe: F.run.classe, t: Date.now() }; F.run = null; saveGame(); renderSonges(); }
