        const head = I.boss && (I.known || (run && FRIG.main.includes(I.p.nom))) ? FRIG_ART.heads[I.p.nom] : (!run && I.boss && f >= 30) ? FRIG_ART.heads[FRIG.main[f / 5 - 6]] : '';
