    const rm = rareM(playerStats().dropPct), D = Object.fromEntries(Object.entries(FRIG.drop).map(([k, v]) => [k, v * rm])), pc = v => String(Math.round(v * 10000) / 100).replace('.', ',') + ' %', L = [];
