        { titre: 'Combat à Brâkmar', url: OST + 'wogqkbbc/16.%20Combat%20A%20Br%C3%A2kmar.mp3' },
        { titre: 'Dofus Final', url: OST + 'sgdxdyhp/24.%20Dofus%20Final.mp3' },
        { titre: 'Brâkmar', url: OST + 'xtbzssio/15.%20Br%C3%A2kmar.mp3' },
        { titre: 'Combat en Amakna', url: OST + 'wvqqfgny/05.%20Combat%20En%20Amakna.mp3' }
